import subprocess,pathlib
remote="python3 - <<'INNER'\nimport hashlib,json,pathlib,subprocess,tarfile,time\nr=pathlib.Path('/dataset/shaoshitong/search-r1-rl/topd');archive=r/'tools/qwen25-32b-startup-guard-candidate-v4.tar.gz'\nassert hashlib.sha256(archive.read_bytes()).hexdigest()=='e9e174740fde91287cf98629b7e9f3d876aafb3cf78083da075b7442efbc4f84'\ntarget=r/'tools/qwen25-32b-startup-guard-candidate-v4';target.mkdir(exist_ok=True)\nwith tarfile.open(archive) as t:\n for m in t.getmembers():\n  assert m.isfile() and '/' not in m.name and m.name not in ('.','..')\n  b=t.extractfile(m).read();p=target/m.name\n  if p.exists():assert p.read_bytes()==b\n  else:p.write_bytes(b)\nfor n,h in json.loads((target/'files.json').read_text()).items():assert hashlib.sha256((target/n).read_bytes()).hexdigest()==h\nentry=r/'tools/startup-guard-v4-native-cpu.sbatch'\nassert hashlib.sha256(entry.read_bytes()).hexdigest()=='cc1f3457273ed56ece077e0dfe694f9a6a015a6b19965d71e654ff134a99f9bc'\nrecord=r/'logs/topd-startup-guard-cpu-v4-submission.json'\nif record.exists():\n d=json.loads(record.read_text());assert d['status']=='SUBMITTED',d\nelse:\n q=subprocess.check_output(['squeue','-h','-o','%i|%j'],text=True);assert not any(x.split('|',1)[-1]=='topd-startup-guard-cpu-v4' for x in q.splitlines())\n d=dict(status='UNKNOWN_BEFORE_SUBMISSION',scope='CPU_CONTRACT_NO_GPU_NO_QUALITY',entry=str(entry),epoch=time.time())\n record.write_text(json.dumps(d,indent=2)+'\\n')\n jid=subprocess.check_output(['sbatch','--parsable',str(entry)],text=True).strip().split(';')[0];assert jid.isdigit()\n d.update(status='SUBMITTED',job_id=int(jid));record.write_text(json.dumps(d,indent=2)+'\\n')\nprint(json.dumps(d))\nINNER"
p=subprocess.run(["python3","work/remote_topd.py"],input=remote,text=True,capture_output=True)
print(p.stdout,end="");print(p.stderr,end="")
if not p.returncode:pathlib.Path("outputs/topd-startup-guard-cpu-v4-submission.json").write_text(p.stdout)
raise SystemExit(p.returncode)
